    <?php foreach ($logs as $log): ?><tr data-audit="<?= escapeHtml(json_encode($log, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR)) ?>"><td><strong class="audit-time"><?= date('H:i:s', strtotime($log['created_at'])) ?></strong><small><?= date('d/m/Y', strtotime($log['created_at'])) ?></small></td><td><div class="account-identity"><span class="avatar"><?= escapeHtml(mb_substr($log['full_name'], 0, 1)) ?></span><div><strong><?= escapeHtml($log['full_name']) ?></strong><small><?= escapeHtml($log['username'] ?? 'Tự động') ?></small></div></div></td><td><span class="audit-action <?= in_array($log['action'], ['cancel', 'lock', 'deactivate', 'delete'], true) ? 'audit-warning' : ($log['action'] === 'create' ? 'audit-created' : 'audit-updated') ?>"><?= escapeHtml($log['action_name']) ?></span></td><td><strong class="audit-reference"><?= escapeHtml($log['reference']) ?><span><?= escapeHtml($log['entity_name']) ?></span></strong><small><?= escapeHtml($log['description']) ?></small></td><td><?= escapeHtml($log['warehouse_name']) ?></td><td><button class="button audit-details" type="button" aria-label="Xem nhật ký <?= $log['id'] ?>">Xem</button></td></tr><?php endforeach; ?>
    </tbody></table></div><p class="empty-state audit-empty" hidden>Không tìm thấy thao tác phù hợp. Hãy thử khoảng ngày hoặc bộ lọc khác.</p><div class="table-footer account-table-footer"><span id="audit-count" role="status">Hiển thị <?= count($logs) ? 1 : 0 ?>–<?= min(10, count($logs)) ?> / <?= count($logs) ?> bản ghi</span><nav class="account-pagination" aria-label="Phân trang nhật ký"><span>10 dòng / trang</span><button id="audit-page-previous" class="button" type="button" aria-label="Trang trước" disabled>Trước</button><span id="audit-page-label" aria-live="polite">1 / <?= max(1, (int) ceil(count($logs) / 10)) ?></span><button id="audit-page-next" class="button" type="button" aria-label="Trang sau">Sau</button></nav></div>
